import {commerceProducts,travelProducts,commerceProduct,productLinkAllowed} from './commerce-catalog.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const amazonTaskCopy={
 'search-results':{title:'Поисковая выдача',hint:'Поисковая фраза',example:'water bottle',prompt:'Хочу сравнить предложения в поисковой выдаче Amazon.'},
 search:{title:'Найти товары',hint:'Что искать в Amazon',example:'insulated water bottle',prompt:'Хочу сравнить термобутылки на Amazon: цены и рейтинги.'},
 products:{title:'Карточки товаров',hint:'Ссылка на товар Amazon',example:'https://www.amazon.com/dp/B0CRMZHDG8',prompt:'Хочу получить цену и характеристики этого товара.'},
 reviews:{title:'Отзывы',hint:'Ссылка на товар Amazon',example:'https://www.amazon.com/dp/B094NC89P9',prompt:'Хочу собрать отзывы о товаре для разбора жалоб покупателей.'},
 sellers:{title:'Продавец',hint:'Ссылка на страницу продавца Amazon',example:'https://www.amazon.com/sp?seller=…',prompt:'Нужна публичная информация о продавце.'},
 bestsellers:{title:'Бестселлеры',hint:'Ссылка на раздел Best Sellers',example:'https://www.amazon.com/Best-Sellers/zgbs',prompt:'Хочу посмотреть бестселлеры в выбранной категории.'},
 category:{title:'Категория',hint:'Ссылка на категорию Amazon',example:'https://www.amazon.com/…',prompt:'Хочу сравнить товары из этой категории.'},
 brand:{title:'Бренд',hint:'Ссылка на страницу бренда Amazon',example:'https://www.amazon.com/stores/…',prompt:'Хочу изучить ассортимент бренда.'},
 'seller-products':{title:'Ассортимент продавца',hint:'Ссылка на продавца Amazon',example:'https://www.amazon.com/sp?seller=…',prompt:'Хочу получить список товаров этого продавца.'},
 upc:{title:'По штрихкоду',hint:'Штрихкод UPC',example:'012345678905',prompt:'Найти товар по штрихкоду.'}
};
function productCard(p){return `<article class="commerce-card"><div class="commerce-card-heading"><span class="commerce-mark">${esc(p.mark)}</span><div><h2>${esc(p.name)}</h2><small>${esc(p.audience)}</small></div></div><p>${esc(p.summary)}</p><div class="amazon-tags">${p.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p class="fine">${esc(p.scope)}</p><a class="primary" href="#product/${p.id}">Обсудить задачу с ${esc(p.name)} →</a></article>`;}
export function ecommercePage(){return `<section class="commerce-intro"><div class="overline">КАТАЛОГ / E-COMMERCE</div><h1>Что хотите узнать<br>о товарах и конкурентах?</h1><p>Выберите магазин. Ассистент уточнит задачу и подготовит нужный сбор: товары, цены, отзывы или ассортимент. Все действия и результаты — в Affsiwen.</p><div class="commerce-summary"><strong>${commerceProducts.length} продуктов</strong><span>Один чат на каждую площадку</span><span>Таблица + CSV</span></div></section><section class="commerce-grid" aria-label="Продукты E-commerce">${commerceProducts.map(productCard).join('')}</section><section class="commerce-note"><h2>Вы покупаете конкретный результат</h2><p>Например: до 10 предложений наушников с ценами и ссылками, отзывы о выбранном товаре или ассортимент магазина. Набор полей и доступный объём уточняются до запуска. Цена будет рассчитана по фактическим расходам пилота; оплата пока не включена.</p><p>Каждый продукт показывает свой статус подключения. Наличие инструмента не гарантирует полноту полей или количество найденных записей.</p></section>`;}
export function travelPage(){return `<section class="commerce-intro"><div class="overline">КАТАЛОГ / TRAVEL</div><h1>Изучайте отели<br>и предложения аренды.</h1><p>Для отельеров, управляющих жильём и аналитиков: данные конкурентов в таблице, без ручного переноса карточек. Выберите площадку и опишите задачу в чате.</p><div class="commerce-summary"><strong>${travelProducts.length} продуктов</strong><span>Отдельный чат и история</span><span>Таблица + CSV</span></div></section><section class="commerce-grid" aria-label="Продукты Travel">${travelProducts.map(productCard).join('')}</section><section class="commerce-note"><h2>Что вы получаете</h2><p>Сведения об объектах по ссылкам; в Booking.com и Airbnb — также поиск по месту, датам и гостям. Для Agoda в этой версии подключены карточки без сбора цен на выбранные даты.</p><p>Это исследование предложений, не сервис бронирования. Наличие и цены меняются; налоги, состав гостей, даты и валюту нужно учитывать отдельно. Оплата пока не включена.</p></section>`;}
export function amazonHome(){return `<section class="commerce-intro"><div class="overline">AFFSIWEN / ДАННЫЕ ДЛЯ БИЗНЕСА</div><h1>Товары, отели и конкуренты.<br><em>Спросите в чате.</em></h1><p>Исследуйте ассортимент магазинов, отели и предложения аренды. Выберите площадку, объясните задачу — получите понятный состав запроса и результат в таблице.</p><a class="primary" href="#e-commerce">E-commerce · ${commerceProducts.length} продуктов →</a> <a class="secondary" href="#travel">Travel · ${travelProducts.length} продуктов →</a></section><section class="commerce-grid">${commerceProducts.slice(0,3).map(productCard).join('')}</section><section class="commerce-note"><h2>От вопроса к данным</h2><ol class="journey-steps"><li><span class="step-no">01</span><h3>Выберите площадку</h3><p>Магазин из E-commerce или площадку размещения из Travel.</p></li><li><span class="step-no">02</span><h3>Опишите задачу</h3><p>Ассистент уточнит фразу или ссылку, рынок и объём.</p></li><li><span class="step-no">03</span><h3>Подтвердите запрос</h3><p>Проверьте, какие поля и сколько записей ожидаются. Статус запуска указан в продукте.</p></li><li><span class="step-no">04</span><h3>Работайте с результатом</h3><p>Полученные строки можно обсудить с ассистентом и скачать в CSV.</p></li></ol></section>`;}
const euro=c=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR'}).format(c/100);
export function amazonPage({connection=null,messages=[],answer=null,plan=null,quote=null,result=null,error='',pending=false,text='',mode='preview',image=null,run=null,launching=false,product=commerceProduct('amazon')}={}){
 result=run?.result||result;const collecting=run&&['starting','running','reserved'].includes(run.status);const sameRun=run?.planId===plan?.id;
 const productName=esc(product.name),exportPath=product.id==='amazon'?'/api/amazon/export':'/api/commerce/'+product.id+'/export';
 const conversational=messages.length>0,preview=(connection?.assistantMode||mode)!=='llm';
 return `<section class="amazon-chat-heading"><a class="quiet-link" href="#${product.category==='Travel'?'travel':'e-commerce'}">${product.category||'E-commerce'} / ${productName}</a><div class="overline">${productName} · AFFSIWEN</div><h1>Что хотите узнать<br>о ${productName}?</h1><p>Опишите задачу. Я уточню детали и подготовлю состав результата. Стоимость будет подтверждена до оплаты.</p><div class="chat-mode"><span class="pill ${preview?'amber':'green'}">${preview?'Демо диалога':'AI-ассистент'}</span><span>${preview?'Сценарий знакомства с продуктом. Свободный AI-диалог ещё не подключён.':'Ассистент помогает с запросом. Запуск — только после вашего подтверждения.'}</span></div><p class="fine">${esc(product.scope)}</p><p class="fine">${connection?(connection.connected?'Подключение данных проверено. Возможности конкретного запроса уточним в чате.':'Источник данных сейчас недоступен. Повторите позже.'):'Проверяем подключение…'}</p></section><section class="amazon-chat-shell" aria-label="Ассистент ${productName}"><div class="amazon-chat-top"><span><i class="chat-orb">a</i> Ваш помощник по ${productName}</span>${conversational&&!collecting?'<button class="text-button" data-action="amazon-reset">Новый запрос</button>':''}</div><div class="amazon-transcript" aria-live="polite" aria-busy="${pending}">${conversational?messages.map(m=>`<article class="chat-bubble ${m.role==='user'?'from-user':'from-assistant'}"><small>${m.role==='user'?'Вы':'Affsiwen'}</small>${m.hasImage?'<small class="chat-photo-note">Фото приложено · сохранено его описание</small>':''}<p>${esc(m.content)}</p></article>`).join(''):`<article class="chat-bubble from-assistant"><small>Affsiwen</small><p>${esc(product.summary)} Расскажите, какой результат вам нужен.</p><p>Я помогу сформулировать запрос. До запуска вы увидите, что получите и сколько это будет стоить.</p></article>`}${pending?`<article class="chat-bubble from-user"><small>Вы</small><p>${esc(text)}</p></article><div class="chat-thinking" role="status">Готовлю следующий шаг…</div>`:''}</div>${!pending&&!plan?`<div class="chat-suggestions">${(answer?.options?.length?answer.options:!conversational?product.examples:[]).map(v=>`<button data-action="amazon-suggestion" data-value="${esc(v)}">${esc(v)} →</button>`).join('')}</div>`:''}${plan?`<section class="amazon-offer"><div class="overline">ВАШЕ ПРЕДЛОЖЕНИЕ</div><div class="offer-heading"><h2>${esc(plan.title)}</h2><div class="offer-price">${quote?euro(quote.priceCents):'Цена готовится'}<small>${quote?'за этот запрос · предварительно':'оплата пока недоступна'}</small></div></div><p class="offer-brief">${esc(plan.value)} · ${productName} ${esc(plan.market==='GLOBAL'?'':plan.market)}</p>${plan.travel?`<p class="fine">Заезд: ${esc(plan.travel.checkIn)} · выезд: ${esc(plan.travel.checkOut)} · взрослых: ${esc(plan.travel.adults)} · детей: ${esc(plan.travel.children)} · младенцев: ${esc(plan.travel.infants)}${plan.travel.pets!==undefined?` · питомцев: ${esc(plan.travel.pets)}`:''}${plan.travel.rooms?` · номеров: ${esc(plan.travel.rooms)}`:''} · валюта: ${esc(plan.travel.currency)}</p>`:''}<ul><li>До ${plan.limit} записей. Фактическое количество зависит от доступных данных.</li><li>${esc(plan.columns.join(', '))}.</li><li>Таблица в Affsiwen и файл CSV.</li></ul><p class="fine">${esc(quote?.notice||'Состав запроса подготовлен. Стоимость подтвердим после расчёта реальных расходов; сейчас ничего не списываем.')}</p>${!sameRun?`<button class="primary full" data-action="amazon-run" ${!connection?.execution?.enabled||plan.limit>10||pending||launching?'disabled':''}>${launching?'Запускаем сбор…':'Получить реальные данные'}</button><p class="fine">${connection?.execution?.enabled?(plan.limit>10?'Для пробного сбора уменьшите объём до 10 записей сообщением в чате.':'Нажатие запускает сбор этого запроса. В пилоте расходы несёт Affsiwen. Повторный клик не создаёт новый сбор.'):'Реальный запуск готовится к включению.'}</p>`:''}</section>`:''}${run?`<section class="amazon-run-status" role="status"><strong>${esc(run.message)}</strong><p>${esc(run.task)} · до ${run.requested} записей</p>${['starting','running'].includes(run.status)?'<button class="text-button" data-action="amazon-poll">Проверить статус</button>':''}${run.status==='reserved'||run.status==='unknown'?'<p>Автоматический платный повтор запрещён. Мы сохранили состояние для проверки.</p>':''}</section>`:''}${result?`<section class="amazon-result"><h2>${result.synthetic?'Пример выдачи':'Результат запроса'}</h2><span class="pill ${result.synthetic?'amber':'green'}">${result.synthetic?'ДЕМО · ВЫМЫШЛЕННЫЕ ДАННЫЕ':'РЕАЛЬНЫЕ ДАННЫЕ'}</span>${!result.synthetic?`<p class="fine">Получено ${result.rows.length} из запрошенных ${result.requested}. ${esc(result.notice)}<br>Собрано: ${esc(new Date(result.createdAt).toLocaleString('ru-RU'))}</p>`:''}<div class="sample-table"><table><caption>${esc(result.title)} · ${result.rows.length} ${result.synthetic?'демонстрационных':'полученных'} строк</caption><thead><tr>${Object.keys(result.rows[0]||{}).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${result.rows.map(r=>`<tr>${Object.values(r).map(v=>`<td>${typeof v==='string'&&productLinkAllowed(v,product)?`<a href="${esc(v)}" target="_blank" rel="noopener noreferrer">Открыть на ${productName} ↗</a>`:esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><a class="secondary" href="${exportPath}">${result.synthetic?'Скачать демо CSV':'Скачать CSV'}</a></section>`:''}${error?`<div class="amazon-error" role="alert">${esc(error)}</div>`:''}<form id="amazon-chat" class="amazon-composer"><label for="amazon-message">Ваше сообщение</label>${image?`<div class="chat-photo-preview"><img src="data:${esc(image.mediaType)};base64,${esc(image.data)}" alt="Фото к вашему запросу"><span>Фото готово к отправке</span><button type="button" class="text-button" data-action="amazon-remove-image" ${pending||collecting||launching?'disabled':''}>Убрать</button></div>`:''}<textarea id="amazon-message" name="message" required minlength="2" maxlength="2000" placeholder="${esc(product.examples[0])}" ${pending||collecting||launching?'disabled':''}>${pending?'':esc(text)}</textarea><div class="chat-upload"><label class="secondary">＋ Фото<input id="amazon-photo" type="file" accept="image/jpeg,image/png,image/webp" ${pending||collecting||launching||preview?'disabled':''}></label><small>${preview?'Фото станет доступно после подключения AI.':'Одно фото JPEG, PNG или WebP. При отправке оно передаётся AI для ответа; в истории сохраняется описание.'}</small></div><div><small>Запуск сбора и оплата требуют отдельного подтверждения.</small><button class="primary" ${pending||collecting||launching?'disabled':''}>${pending?'Отвечаю…':'Отправить ↑'}</button></div></form></section><section class="chat-how"><div><span>01</span><strong>Ваша задача</strong><p>Простыми словами, без выбора инструментов.</p></div><div><span>02</span><strong>Понятное предложение</strong><p>Результат, объём и сумма до запуска.</p></div><div><span>03</span><strong>Данные у вас</strong><p>Таблица и выгрузка в одном месте.</p></div></section>`;
}
